# Preflight hash checks BEFORE making changes. An unfamiliar local version is not overwritten.
foreach ($entry in $files) {
    $rel = $entry.Replace('/',[IO.Path]::DirectorySeparatorChar)
    $target = Join-Path $root $rel
    if (-not (Test-Path -LiteralPath $target -PathType Leaf)) {
        throw ('Expected StockFlow file missing: ' + $entry + '. Make sure Roles update is installed.')
    }
    $digest = (Get-FileHash -LiteralPath $target -Algorithm SHA256).Hash.ToUpperInvariant()
    if ($digest -ne $expected[$entry]) {
        throw ('File differs from expected Roles version: ' + $entry + '. Nothing changed. Send an up-to-date project ZIP to merge safely.')
    }
}
