'@
$temp = Join-Path ([IO.Path]::GetTempPath()) ('StockFlow-Alignment-' + [Guid]::NewGuid().ToString('N'))
$unpacked = Join-Path $temp 'payload'
$archive = Join-Path $temp 'patch.zip'
$backup = Join-Path ([IO.Path]::GetTempPath()) ('StockFlow-Alignment-Backup-' + (Get-Date -Format 'yyyyMMdd-HHmmss'))
New-Item -ItemType Directory -Path $temp -Force | Out-Null
New-Item -ItemType Directory -Path $backup -Force | Out-Null
try {
    [IO.File]::WriteAllBytes($archive, [Convert]::FromBase64String(($encoded -replace '\s','')))
    Expand-Archive -LiteralPath $archive -DestinationPath $unpacked -Force
    foreach ($entry in $files) {
        $rel = $entry.Replace('/',[IO.Path]::DirectorySeparatorChar)
        if (-not (Test-Path -LiteralPath (Join-Path $unpacked $rel) -PathType Leaf)) {
            throw ('Installer payload is incomplete: ' + $entry)
        }
        $dst = Join-Path $backup $rel
        New-Item -ItemType Directory -Path (Split-Path -Parent $dst) -Force | Out-Null
        Copy-Item -LiteralPath (Join-Path $root $rel) -Destination $dst -Force
    }
    $written = New-Object 'System.Collections.Generic.List[string]'
    try {
        foreach ($entry in $files) {
            $rel = $entry.Replace('/',[IO.Path]::DirectorySeparatorChar)
            Copy-Item -LiteralPath (Join-Path $unpacked $rel) -Destination (Join-Path $root $rel) -Force
            $written.Add($rel)
        }
    } catch {
        foreach ($rel in $written) {
            Copy-Item -LiteralPath (Join-Path $backup $rel) -Destination (Join-Path $root $rel) -Force
        }
        throw
    }
    Write-Host ''
    Write-Host 'SUCCESS: StockFlow role alignment installed.' -ForegroundColor Green
    Write-Host 'Role-specific dashboards, menu and page access updated.'
    Write-Host 'Trading-point managers can view purchases only for their point.'
    Write-Host 'Suppliers are accessible only by director and supply manager.'
    Write-Host 'Sellers see products currently in stock at their assigned point.'
    Write-Host 'Director may administratively create sellers.'
    Write-Host ('Backup: ' + $backup) -ForegroundColor Yellow
    Write-Host 'NEXT: Ctrl+Shift+B, restart, sign out and sign in again.' -ForegroundColor Cyan
} finally {
    Remove-Item -LiteralPath $temp -Recurse -Force -ErrorAction SilentlyContinue
}
